    // At runtime we simply allocate a new Vec<u8> of the requested capacity
    // and push each byte in turn.

    let mut result = Vec::with_capacity(count);
    let mut i = 0;
    while i < count {
        // safe because offset + count <= buffer.len()
        result.push(buffer[offset + i]);
        i += 1;
    }
    result
